//! Percussion protection parity with the Python reference
//! (`tools/src/pressing_tools/protect/rhythm.py`).
//!
//! 1. Event level (committed `tests/fixtures/protect_decisions.json`): the
//!    rhythm flag and the final keep decision of every candidate region.
//! 2. End to end (git-ignored `runtime/fixtures-protect/<case>/`, generated by
//!    `tools/scripts/export_protect_fixtures.py`): the protected engine driven
//!    by the reference scores must reproduce the kept-region masks and the
//!    repaired audio. Skipped when the directory is absent.

use std::path::Path;

use pressing_core::protect::{ProtectConfig, Protector};
use pressing_core::{Declicker, Model, Protection, ScoreSource};

const QUIET: f32 = -100.0;

// ---- Event level ----

#[test]
fn rhythm_flags_and_decisions_match_reference() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/protect_decisions.json");
    let cases: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let model = Model::embedded();
    let mut total = 0usize;
    for case in cases.as_array().unwrap() {
        let sr = case["sample_rate"].as_f64().unwrap();
        let regions = case["regions"].as_array().unwrap();
        for (mode, m) in case["modes"].as_object().unwrap() {
            let future = m["future_s"].as_f64().unwrap();
            let mut p = Protector::new(ProtectConfig::with_future(future), &model.post, sr, 1);
            for (c, evs) in case["events"].as_array().unwrap().iter().enumerate() {
                for e in evs.as_array().unwrap() {
                    p.test_push_event(c, e[0].as_u64().unwrap(), e[1].as_f64().unwrap());
                }
            }
            let want_r: Vec<bool> = m["rhythmic"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_bool().unwrap())
                .collect();
            let want_k: Vec<bool> = m["keep"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_bool().unwrap())
                .collect();
            let regs: Vec<(usize, u64, f64)> = regions
                .iter()
                .map(|r| {
                    (
                        r["c"].as_u64().unwrap() as usize,
                        r["peak"].as_u64().unwrap(),
                        r["level"].as_f64().unwrap(),
                    )
                })
                .collect();
            let got_r: Vec<bool> = regs
                .iter()
                .map(|&(_, pk, lv)| p.test_rhythmic(pk, lv))
                .collect();
            let all: Vec<(usize, u64, bool)> = regs
                .iter()
                .zip(&got_r)
                .map(|(&(c, pk, _), &r)| (c, pk, r))
                .collect();
            let got_k: Vec<bool> = regs
                .iter()
                .zip(&got_r)
                .map(|(&(c, pk, _), &r)| p.test_keep(c, pk, r, &all))
                .collect();
            let dr = got_r.iter().zip(&want_r).filter(|(a, b)| a != b).count();
            let dk = got_k.iter().zip(&want_k).filter(|(a, b)| a != b).count();
            let protected = want_k.iter().filter(|k| !**k).count();
            eprintln!(
                "{} {mode}: {} regions, {protected} protected by the reference; rhythm-flag mismatches {dr}, decision mismatches {dk}",
                case["name"], regs.len()
            );
            assert!(protected > 0, "fixture must exercise protection");
            assert_eq!(dr, 0, "rhythm flags differ from the reference");
            assert_eq!(dk, 0, "keep decisions differ from the reference");
            total += regs.len();
        }
    }
    assert!(total > 0);
}

// ---- End to end ----

struct FixtureScores {
    scores: [Vec<f32>; 2],
    delay: usize,
    n: usize,
}

impl ScoreSource for FixtureScores {
    fn push(&mut self, _l: f32, _r: f32) -> Option<[[f32; 4]; 2]> {
        let n = self.n;
        self.n += 1;
        if n % 4 != 3 {
            return None;
        }
        let mut out = [[0.0; 4]; 2];
        for (c, o) in out.iter_mut().enumerate() {
            for (k, v) in o.iter_mut().enumerate() {
                let m = n - 3 + k;
                *v = m
                    .checked_sub(self.delay)
                    .and_then(|t| self.scores[c].get(t).copied())
                    .unwrap_or(QUIET);
            }
        }
        Some(out)
    }
    fn delay(&self) -> usize {
        self.delay
    }
    fn reset(&mut self) {
        self.n = 0;
    }
}

fn read_f32(p: &Path) -> Vec<f32> {
    std::fs::read(p)
        .unwrap()
        .as_chunks::<4>()
        .0
        .iter()
        .map(|&c| f32::from_le_bytes(c))
        .collect()
}

fn runs(m: &[u8]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < m.len() {
        if m[i] != 0 {
            let a = i;
            while i < m.len() && m[i] != 0 {
                i += 1;
            }
            out.push((a, i));
        } else {
            i += 1;
        }
    }
    out
}

#[test]
fn protected_engine_matches_reference_end_to_end() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures-protect");
    let Ok(dirs) = std::fs::read_dir(&root) else {
        eprintln!("skipping: {} not present", root.display());
        return;
    };
    let model = Model::embedded();
    let d = model.net.d;
    let mut cases: Vec<_> = dirs
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.join("manifest.json").exists())
        .collect();
    cases.sort();
    for dir in cases {
        let man: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(dir.join("manifest.json")).unwrap())
                .unwrap();
        let len = man["samples"].as_u64().unwrap() as usize;
        let edge = man["edge_ignore"].as_u64().unwrap() as usize;
        let audio = read_f32(&dir.join("audio.bin"));
        let scores = read_f32(&dir.join("scores.bin"));
        let (l, r) = audio.split_at(len);
        for (mode, prot) in [
            ("standard", Protection::Standard),
            ("extended", Protection::Extended),
        ] {
            let src = FixtureScores {
                scores: [scores[..len].to_vec(), scores[len..].to_vec()],
                delay: d,
                n: 0,
            };
            let mut eng = Declicker::with_score_source_protected(&model, Box::new(src), prot);
            let out = eng.process_offline_with_masks(l, r);
            let want = std::fs::read(dir.join(format!("mask_{mode}.bin"))).unwrap();
            let rep = read_f32(&dir.join(format!("repaired_{mode}.bin")));
            let mut ref_runs = 0;
            let mut diff_runs = 0;
            let mut max_err = 0.0f32;
            for c in 0..2 {
                let w = &want[c * len..(c + 1) * len];
                let g = &out.masks[c];
                let inner = |v: &[(usize, usize)]| {
                    v.iter()
                        .copied()
                        .filter(|&(a, b)| a >= edge && b <= len - edge)
                        .collect::<Vec<_>>()
                };
                let (rw, rg) = (inner(&runs(w)), inner(&runs(g)));
                ref_runs += rw.len();
                diff_runs += rw.iter().filter(|x| !rg.contains(x)).count()
                    + rg.iter().filter(|x| !rw.contains(x)).count();
                let y = if c == 0 { &out.left } else { &out.right };
                for i in edge..len - edge {
                    if w[i] == g[i] {
                        max_err = max_err.max((y[i] - rep[c * len + i]).abs());
                    }
                }
            }
            let st = eng.stats();
            eprintln!(
                "{} {mode}: latency {} | ref runs {ref_runs}, differing {diff_runs} | max |err| where masks agree {max_err:.2e} | deadline misses {}",
                dir.file_name().unwrap().to_string_lossy(),
                eng.latency_samples(),
                st.deadline_misses
            );
            assert_eq!(st.deadline_misses, 0);
            assert!(
                diff_runs * 100 <= ref_runs.max(1),
                "more than 1% of runs differ"
            );
            assert!(max_err < 1e-4, "repaired audio differs");
        }
    }
}

#[test]
fn rotation_periodic_scratch_is_vetoed() {
    // Events every 0.2 s (a beat) plus one channel's scratch exactly every 1.8 s.
    let model = Model::embedded();
    let mut p = Protector::new(ProtectConfig::with_future(1.0), &model.post, 48_000.0, 1);
    let sr = 48_000u64;
    let mut beat: Vec<u64> = (0..60).map(|k| 2 * sr + k * sr / 5).collect();
    beat.sort_unstable();
    let scratch: Vec<u64> = (0..5).map(|k| sr + k * 86_400).collect(); // 1.8 s
    let mut all: Vec<(usize, u64)> = beat
        .iter()
        .map(|&s| (1, s))
        .chain(scratch.iter().map(|&s| (0, s)))
        .collect();
    all.sort_unstable_by_key(|x| x.1);
    for &(c, s) in &all {
        p.test_push_event(c, s, -20.0);
    }
    let pk = scratch[3]; // 6.4 s: inside the beat, with scratches 1.8 and 3.6 s earlier
    let rhythmic = p.test_rhythmic(pk, -20.0);
    let keep = p.test_keep(0, pk, true, &[(0, pk, true)]);
    eprintln!("scratch at beat time: rhythmic {rhythmic}, kept (repaired) {keep}");
    assert!(keep, "a rotation-periodic scratch must still be repaired");
}
